<?php include 'db.php'; require_role('Admin'); $allowed=['PATIENT','DOCTOR','NURSE','ROOM','RADIOLOGY_TEST','APPOINTMENT','PAYMENT','FILE_UPLOAD','MEDICAL_STATUS','RADIOLOGY_REPORT']; $table=in_array($_GET['table']??'', $allowed)?$_GET['table']:'PATIENT'; $page_title='Manage '.$table; include 'header.php'; ?>
